import os
import pandas as pd
import xgboost as xgb
from sklearn.model_selection import train_test_split
from sklearn.metrics import accuracy_score, classification_report

def train_and_save_model():
    print("[Phase 2] Loading pre-processed data...")
    
    # Path to the CSV file generated by data_loader.py in Phase 1
    data_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data", "btc_usdt_1h_features.csv")
    
    try:
        df = pd.read_csv(data_path)
        print(f"Successfully loaded data. Shape: {df.shape}")
    except FileNotFoundError:
        print(f"Error: Could not find '{data_path}'. Please ensure Phase 1 (data_loader.py) has run successfully.")
        return

    print("[Phase 2] Splitting Data into Train & Test sets...")
    
    # Define the features we want the model to learn from
    # These match the stationary features we created in Phase 1
    feature_cols = [
        "return_1h", "return_4h", "log_return", "hl_spread", 
        "co_spread", "vol_change", "volatility_10", "rsi_14_norm", 
        "macd_line_pct", "macd_signal_pct", "macd_hist_pct", 
        "ema_20_dist", "ema_50_dist", "ema_cross_20_50", "atr_pct"
    ]
    
    X = df[feature_cols]
    y = df['target']
    
    # 80% for training, 20% for testing. 
    # shuffle=False is critical for time-series data to prevent future leakage.
    X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2, shuffle=False)
    
    print(f"Training shapes -> X: {X_train.shape}, y: {y_train.shape}")
    print(f"Testing shapes  -> X: {X_test.shape}, y: {y_test.shape}")
    
    # Configure the XGBoost Classifier
    model = xgb.XGBClassifier(
        n_estimators=100,      
        learning_rate=0.05,    
        max_depth=4,           
        random_state=42,
        eval_metric='logloss'
    )
    
    print("\n[Phase 2] Training the XGBoost Model...")
    model.fit(X_train, y_train)
    
    print("[Phase 2] Evaluating the Model...")
    y_pred = model.predict(X_test)
    
    # Check Accuracy
    accuracy = accuracy_score(y_test, y_pred)
    print(f"\n✅ Model Accuracy on Unseen Data: {accuracy * 100:.2f}%\n")
    print("Classification Report:")
    print(classification_report(y_test, y_pred, target_names=["SELL/HOLD (0)", "BUY (1)"]))
    
    # Save the trained model (use absolute path for consistency)
    model_filename = os.path.join(os.path.dirname(os.path.abspath(__file__)), "xgb_model.json")
    model.save_model(model_filename)
    print(f"💾 Model successfully saved as '{model_filename}'")

if __name__ == "__main__":
    train_and_save_model()